# HIP kernel for fused bias addition and scaling
fused_bias_scale_source = """
#include <hip/hip_runtime.h>
#include <torch/extension.h>

__global__ void fused_bias_scale_kernel(float* x, const float* bias, float factor, int rows, int cols) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total_elements = rows * cols;
    if (idx < total_elements) {
        int col = idx % cols;
        x[idx] = (x[idx] + bias[col]) * factor;
    }
}

void fused_bias_scale_hip(torch::Tensor x, torch::Tensor bias, float factor) {
    int rows = x.size(0);
    int cols = x.size(1);
    int total_elements = rows * cols;

    const int block_size = 256;
    const int num_blocks = (total_elements + block_size - 1) / block_size;

    fused_bias_scale_kernel<<<num_blocks, block_size>>>(
        x.data_ptr<float>(),
        bias.data_ptr<float>(),
        factor,
        rows,
        cols
    );
}
"""

fused_bias_scale_op = load_inline(
    name="fused_bias_scale",
    cpp_sources=fused_bias_scale_source,
    functions=["fused_bias_scale_hip"],
    verbose=True,
)

