    def __init__(self, in_features, out_features, scaling_factor):
        super(ModelNew, self).__init__()
        self.matmul = nn.Linear(in_features, out_features)
        self.scaling_factor = scaling_factor
        self.factor = 1.0 + scaling_factor

    def forward(self, x):
        # We perform the matrix multiplication first (without bias for now)
        # weight is (out_features, in_features)
        # x is (batch_size, in_features)
        # res = x @ weight.T
        res = torch.matmul(x, self.matmul.weight.t())

        # Then we use our custom HIP kernel to add bias and scale
        fused_bias_scale_op.fused_bias_scale_hip(res, self.matmul.bias, self.factor)

        return res

