# Custom HIP kernel to perform elementwise scaling
# This can be used to pre-process weights or to scale the output.
scale_kernel_source = """
#include <hip/hip_runtime.h>
#include <torch/extension.h>

__global__ void scale_kernel(float* data, float factor, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        data[idx] *= factor;
    }
}

void scale_tensor_hip(torch::Tensor data, float factor) {
    int size = data.numel();
    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;
    scale_kernel<<<num_blocks, block_size>>>(data.data_ptr<float>(), factor, size);
}
"""

scale_op = load_inline(
    name="scale_op",
    cpp_sources=scale_kernel_source,
    functions=["scale_tensor_hip"],
    verbose=True,
)

